-- Update only explicit privacy contexts in the currently installed definitions.
-- CREATE OR REPLACE preserves each function's owner, signature and existing ACL;
-- it also retains the marketing-consent integration from the preceding migration.
-- Never replace the shared old literal globally: it is still the terms version.
do $migration$
declare routine record; definition text;
begin
 for routine in select * from (values
  ('private.get_account_lifecycle()',
   $old$'privacyVersion','2026-11-23.1'$old$, $new$'privacyVersion','2026-11-24'$new$),
  ('private.complete_parent_onboarding(text,text,boolean,boolean,text)',
   $old$p_privacy_version is distinct from '2026-11-23.1'$old$, $new$p_privacy_version is distinct from '2026-11-24'$new$),
  ('private.begin_parent_registration(text,text,text,text,text,boolean,boolean)',
   $old$p_privacy_version is distinct from '2026-11-23.1'$old$, $new$p_privacy_version is distinct from '2026-11-24'$new$),
  ('private.complete_parent_registration(text,text)',
   $old$proof.privacy_version<>'2026-11-23.1'$old$, $new$proof.privacy_version<>'2026-11-24'$new$),
  ('private.consent_child_profile(text,boolean,boolean)',
   $old$values(actor,p_child_id,t,'2026-11-23.1',true)$old$, $new$values(actor,p_child_id,t,'2026-11-24',true)$new$),
  ('private.billing_defaults()',
   $old$'privacyVersion','2026-11-23.1'$old$, $new$'privacyVersion','2026-11-24'$new$)
 ) as changes(signature,old_fragment,new_fragment)
 loop
  definition:=pg_catalog.pg_get_functiondef(routine.signature::regprocedure);
  if strpos(definition,routine.old_fragment)=0 then
   raise exception 'Expected current privacy context missing: %',routine.signature;
  end if;
  execute replace(definition,routine.old_fragment,routine.new_fragment);
 end loop;

 -- Advance only the current offer's information version, with a fresh revision.
 -- Existing billing history, reservations and purchase document snapshots stay exact.
 perform private.billing_lock();
 update private.billing_control
 set settings=jsonb_set(settings,'{privacyVersion}','"2026-11-24"'::jsonb)
 where singleton and settings->>'privacyVersion' is distinct from '2026-11-24';
 if found then
  perform private.billing_bump(null,'privacy_information_updated',jsonb_build_object('privacyVersion','2026-11-24'));
 end if;
end $migration$;
